using NovaHarvest.Core.NPC;namespace NovaHarvest.Core.Systems;public sealed class ColonySystem {readonly NPCManager _npc;readonly HashSet<string> _members=new();public int MemberCount=>_members.Count;public ColonySystem(NPCManager npc){_npc=npc;}public bool Recruit(string id){var n=_npc.Find(id);if(n is null||n.State!=NPCState.Rescued||_members.Contains(id)||!n.MoveToColony())return false;_members.Add(id);return true;}public bool IsMember(string id)=>_members.Contains(id);public IReadOnlyList<NPC> GetMembers()=>_members.Select(id=>_npc.Find(id)).Where(n=>n is not null).Cast<NPC>().ToList();public bool RemoveMember(string id){if(!_members.Remove(id))return false;_npc.Find(id)?.SetMissing();return true;}}
